import { arrangeZipResults } from './zip-results.js';
import { centerCardOffers } from './center-card-offers.js';
import { cardLocation, cardAddress } from './card-location.js';
import { presentListing } from './directory-policy.js';
import { approvedSlotLabel } from './approved-slot.js';
import { CHAT_QUESTIONS } from './chat-questions.js';
import { centerPhone, formatPhone } from './center-phone.js';
import { groupCode } from './request-code.js';
import { directoryOffer, cardPriceSummary, mostPricesFirst } from './directory-offer.js';
import { paginateGroups } from './pagination.js';
import { calendarFile } from './request-calendar.js';
import { cityState, formatCount, hasPublishedPrice } from './directory-list.js';
// Presentation templates preserved from OneSmarterInc/SelfPay @ bf839ef9af6efde48b2666cc26e7e793a7d9bd06.
// React owns state, rendering and event handling; the old imperative app.js is not loaded.
export function originalUI(context) {
const {account,catalogReady,catalogError,summary,catalogCounts}=context;
const visible=items=>(items||[]).map(item=>presentListing(item));
const DIRECTORY=visible(context.DIRECTORY), offers=centerCardOffers(visible(context.offers)), results=centerCardOffers(visible(context.results));
const state={...context.state,programs:visible(context.state.programs),programEntries:visible(context.state.programEntries),nearbyUnpriced:visible(context.state.nearbyUnpriced)};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BOOKING_ZONES={'America/New_York':'Eastern','America/Chicago':'Central','America/Denver':'Mountain','America/Phoenix':'Arizona','America/Los_Angeles':'Pacific','America/Anchorage':'Alaska','Pacific/Honolulu':'Hawaii'};
function price(o){if(o.card_prices?.length)return o.card_prices.join("\n");if(o.directory_only&&o.published_prices?.length)return o.published_prices.map(p=>p.service+': '+p.text).join('\n');return (o.type==='conflict'||o.type==='quote'||o.amount==null)?'Ask for a price':o.type==='starting'?`From $${o.amount}`:o.type==='range'?`$${o.amount}–$${o.max}`:o.type==='maximum'?`Up to $${o.amount}`:`$${o.amount}`}
function typeLabel(o){if(o.entry?.price_verification==='unverified')return 'Unverified source prices · confirm with facility';return {published:'Published prices · confirm scope',quote:'Price on request',average:'Published average · quote needed',fixed:'Published price',starting:'Starting price · quote needed',range:'Published range · quote needed',maximum:'Published maximum · quote needed',conflict:'Conflicting prices · quote needed'}[o.type]}
function budgetGroup(o,s=state){if(o.directory_only&&s.budget)return 'Budget fit unconfirmed';if(o.budget_status)return o.budget_status;if(!s.budget)return 'No budget set';if(o.type==='fixed'&&o.amount>s.budget)return 'Above your published-price budget';if(o.type==='conflict'||o.type==='maximum'||o.contrast==='unknown'||o.type==='starting'||(o.type==='range'&&o.max>s.budget))return 'Budget fit unconfirmed';return 'Published amount within budget · exact scope needs confirmation'}
function control(id,label,html){return `<div class="field"><label for="${id}">${label}</label>${html}</div>`}
function searchFields(){const fields=[control('radius','Search area',`<select id="radius"><option value="state" ${(state.scope||'state')==='state'?'selected':''}>Entire state</option>${state.scope==='city'?'<option value="city" selected>City only</option>':''}${[25,50,100,250].map(n=>`<option value="${n}" ${state.scope==='radius'&&(state.radius||50)===n?'selected':''}>${n} miles</option>`).join('')}</select>`),control('mod','Imaging service (optional)',`<select id="mod"><option value="">All imaging services</option><option ${state.mod==='MRI'?'selected':''}>MRI</option><option ${state.mod==='CT'?'selected':''}>CT</option></select>`),control('body','Body part / ordered exam (optional)',`<input id="body" value="${esc(state.body)}" placeholder="e.g. Knee">`),control('contrast','Contrast requirement (optional)',`<select id="contrast">${[['unknown',"I'm not sure"],['without','Without contrast'],['with','With contrast'],['both','Without and with contrast']].map(([v,t])=>`<option value="${v}" ${state.contrast===v?'selected':''}>${t}</option>`).join('')}</select>`),control('location','State or city (required)',`<div id="locationPicker" style="position:relative"><div style="display:flex"><input id="location" ${state.spatialActive?'':'required aria-required="true"'} autocomplete="off" value="${esc(state.location)}" placeholder="e.g. Cincinnati, OH" style="min-width:0;flex:1"><button id="locationToggle" type="button" aria-label="Show all location options" aria-expanded="false" aria-controls="cityChoices">▼</button></div><div id="cityChoices" hidden style="position:absolute;top:100%;left:0;right:0;z-index:20;max-height:260px;overflow-y:auto;background:white;border:1px solid #b9cbd4;border-radius:8px;padding:6px;box-shadow:0 4px 12px #0002"></div></div><div id="locationSuggestions" role="status" aria-live="polite"></div>`),control('budget','Budget in USD (optional)',`<input id="budget" type="text" inputmode="numeric" pattern="[0-9]{0,6}" maxlength="6" value="${state.budget||''}">`),control('type','Price status (optional)',`<select id="type">${[['all','All price types'],['fixed','Published fixed'],['starting','Starting prices'],['range','Ranges'],['conflict','Conflicts'],['maximum','Maximums'],['quote','Quote / confirmation required'],['average','Published averages']].map(([v,t])=>`<option value="${v}" ${state.type===v?'selected':''}>${t}</option>`).join('')}</select>`)];return state.nativeApp?fields[1]+fields[2]+fields[3]+fields[4]+`<details class="native-more-filters"><summary>More filters</summary>${fields[0]}${fields[5]}${fields[6]}</details>`:fields.join('');}

function contrastLabel(v){return {without:'Without contrast',with:'With contrast',both:'Without and with contrast',unknown:'Contrast unconfirmed'}[v]||'Contrast unconfirmed'}
function chips(){const parts=[];if(state.mod)parts.push([state.mod,state.body].filter(Boolean).join(' · '));if(state.mod)parts.push(contrastLabel(state.contrast));if(state.currentLocationLabel)parts.push(state.currentLocationLabel);else if(state.location)parts.push(state.location);if(state.budget)parts.push('Budget $'+state.budget);return '<div class="chips">'+parts.map(t=>'<span class="chip">'+esc(t)+'</span>').join('')+'</div>'}
function distanceLabel(o){return Number.isFinite(o.distance_miles)?`${state.spatialActive?o.distance_miles.toLocaleString('en-US',{minimumFractionDigits:1,maximumFractionDigits:1}):Math.round(o.distance_miles)} miles away`:(state.spatialActive?'Distance unavailable — facility coordinates are not listed':'')}
function distanceNote(o){return Number.isFinite(o.distance_miles)?'Straight-line distance to '+(o.distance_precision==='city'?'the city center':o.distance_precision==='zip'?'a ZIP-area reference point':'the facility'):''}
function phoneOf(e){return centerPhone(e)?.display||'';}
function addressOf(e){return cardAddress(e)}
function addressLine(e){const address=addressOf(e);return address?`<div class="card-address muted small">Address: ${esc(address)}</div>`:''}
function websiteOf(e){const url=e?.website||e?.source||'';return /^https?:\/\//.test(url)?url:''}
function telLink(ph,cls,label){const phone=centerPhone({phone:ph});return phone?`<a${cls?` class="${cls}"`:''} href="${esc(phone.href)}">${esc(label||ph)}</a>`:'';}
function contactActions(o){const e=o.entry,addr=addressOf(e),web=websiteOf(e);return `<div class="card-actions" aria-label="Contact ${esc(e.name)}">${e.booking_id?`<button type="button" data-appointment="${esc(e.booking_id)}" data-booking-offer="${esc(o.directory_only?'':o.id||'')}">Request a Time</button>`:''}<button type="button" class="chr-index-button" data-chr="${esc(o.id)}">CHR index</button>${web?`<a href="${esc(web)}" target="_blank" rel="noopener noreferrer">Website</a>`:''}<button type="button" class="details-button" data-detail="${esc(o.id)}">View details</button></div>`}
function regionLine(o){const ent=String(o.entry.entity||'').trim(),region=cardLocation(o);return /^direct operator$/i.test(ent)?region:[region,ent].filter(Boolean).join(' · ')}
function contrastExtra(o){const m=String(o.entry.mri||'').match(/contrast\s*\+\s*\$\s*([\d,]+)/i);if(!m)return '';const mri=/^MRI/i.test(o.mod||'')||/MRI/.test(String(cardPriceSummary(o)??price(o)));return mri&&!(o.contrast==='with'||o.contrast==='both')?`Add $${m[1]} if ordered with contrast`:''}
function scopeLine(o){if(o.card_prices?.length>1)return "Confirm the exact exam and contrast with the facility";const known=o.contrast&&o.contrast!=='unknown';const generic=!o.mod||/^imaging services$/i.test(o.mod);const exam=[generic?'':o.mod,known?contrastLabel(o.contrast):''].filter(Boolean).join(' · ');let scope=String(o.scope||'').replace(/\.$/,'');if(/confirm the exact exam and contrast/i.test(scope))scope='The facility confirms the exact exam and contrast when it calls';else scope=scope.replace(/with the facility/i,'when the facility calls');const dup=known&&/^(MRI|CT)\b/i.test(scope)&&!/confirm/i.test(scope);return [exam,contrastExtra(o),dup?'':scope].filter(Boolean).join(' · ')}
function cardFacts(o){const order=orderText(o);const facts=[];if(o.included&&!/^Confirm/i.test(o.included))facts.push(`<div class="fact"><strong>Price includes</strong><br>${esc(o.included)}</div>`);facts.push(`<div class="fact"><strong>Order</strong><br>${esc(order)}</div>`);if(state.budget)facts.push(`<div class="fact"><strong>Budget check</strong><br>${budgetGroup(o)}</div>`);return `<div class="facts">${facts.join('')}</div>`}
function card(o){if(state.nativeApp)return `<article class="card native-center-card"><div class="row between"><span class="badge ${o.type==='fixed'?'':'warn'}">${typeLabel(o)}</span><label class="small"><input type="checkbox" aria-label="Compare ${esc(o.entry.name)}" data-select="${esc(o.id)}" ${state.selected.includes(o.id)?'checked':''}>Compare</label></div><div class="native-center-title"><h3>${esc(o.entry.name)}</h3><div class="price ${/\$\s*\d/.test(String(cardPriceSummary(o)??price(o)))?'compact-service-prices ':''}${o.directory_only&&o.published_prices?.length?'published-prices':''}">${esc(cardPriceSummary(o)??price(o))}</div></div><p class="native-center-location">${esc(cardLocation(o))} · ${esc(o.entry.entity)}</p>${addressLine(o.entry)}<p class="native-center-distance">${Number.isFinite(o.distance_miles)?`≈ ${o.distance_miles.toLocaleString('en-US',{maximumFractionDigits:1})} mi · ${o.distance_precision==='city'?'city reference':o.distance_precision==='zip'?'ZIP reference':'straight-line'}`:'Distance unavailable'}</p><p class="native-center-protocol">${esc(o.mod)}${o.contrast==='unknown'?'':' · '+esc(contrastLabel(o.contrast))}</p>${o.entry.is_test_center?'<p class="small">Test center · no medical care</p>':''}<button type="button" data-detail="${esc(o.id)}" class="native-view-details">View details <span aria-hidden="true">›</span></button><button type="button" class="chr-index-button" data-chr="${esc(o.id)}">CHR index</button></article>`;return `<article class="card">${o.entry.is_test_center?'<p><span class="badge neutral">TEST CENTER — no medical care</span></p>':''}${o.reviewed_alternative?`<div class="notice"><strong>Reviewed alternative · filters differ</strong><p>${esc(o.match_status)}</p><ul>${(o.filter_differences||[]).map(d=>`<li>${esc(d)}</li>`).join('')}</ul></div>`:''}<div class="row between"><span class="badge ${o.type==='fixed'?'':'warn'}">${typeLabel(o)}</span><label class="compare-check"><input type="checkbox" aria-label="Compare ${esc(o.entry.name)}" data-select="${o.id}" ${state.selected.includes(o.id)?'checked':''}> Compare</label></div><div class="row between" style="margin-top:16px"><div><h3>${esc(o.entry.name)}</h3><div class="muted small">${esc(regionLine(o))}</div>${addressLine(o.entry)}<div class="small" title="${esc(distanceNote(o))}">${esc(distanceLabel(o))}</div></div><div class="price ${/\$\s*\d/.test(String(cardPriceSummary(o)??price(o)))?'compact-service-prices ':''}${o.directory_only&&o.published_prices?.length?'published-prices':''}">${esc(cardPriceSummary(o)??price(o))}</div></div><p class="scope">${esc(scopeLine(o))}</p>${cardFacts(o)}${contactActions(o)}</article>`}
function locationPending(){return !!(state.locationSuggestions?.length||state.locationUnresolved)}
function locationPrompt(){return `<div class="panel" role="status"><h2>${state.locationSuggestions?.length?'Choose your city and state':'Enter a city and state or ZIP code'}</h2><p>${state.locationSuggestions?.length?'More than one location matches your search. Select the correct city beside the location field to find the nearest reviewed offers.':'We could not identify that location. Enter a city with its state, such as Baltimore, MD, or a five-digit ZIP code.'}</p><p>Your city does not need a provider listing in our directory. Once the location is confirmed, we search indexed facilities nationwide and show the nearest options.</p><button id="editLocation" type="button">${state.locationSuggestions?.length?'Choose location':'Update location'}</button></div>`}
function specificOrder(o){return o.order&&!/^(Review the facility restrictions|Not established in this directory)/i.test(o.order)?String(o.order).replace(/[.\s]+$/,''):''}
function questions(o){const exam=state.body||(!o.mod||/^imaging services$/i.test(o.mod)?'exam':o.mod);return [`Does this price apply to my exact ${exam} and the contrast my doctor ordered?`,'What is the all-in amount, including the radiologist, facility, contrast and supplies?','Can I use this self-pay price if I have insurance? Are there any program restrictions?','Do you need a doctor’s order or referral?','Are the report and images included? What are the payment, cancellation and refund terms?']}
function norm(t){return String(t||'').toLowerCase().replace(/[^a-z0-9$]+/g,' ').trim()}
function plainNote(t){const map=[[/^interpretation included$/i,'The radiologist’s reading is included.'],[/^pay at service$/i,'You pay at the time of service.'],[/^rate applies that day$/i,'The rate applies on the day of your visit.']];for(const [rx,out] of map)if(rx.test(t))return out;const c=t.charAt(0).toUpperCase()+t.slice(1);return /[.!?]$/.test(c)?c:c+'.'}
function restrictionsOf(o){const inc=norm(o.included);return String(o.entry.notes||'').split(/;|\.\s+/).map(t=>t.trim().replace(/\.$/,'')).filter(t=>t&&!inc.includes(norm(t))).filter(t=>!/corroborat|linked pdf|\bhtml\b|effective date|source/i.test(t)).filter(t=>{const m=t.match(/apply only to (.+)$/i);return !m||norm(o.entry.name).includes(norm(m[1]))}).map(plainNote)}
function facilityMap(entry){
 const locations=(entry.locations||[]).filter(l=>Number.isFinite(l.latitude)&&Math.abs(l.latitude)<=90&&Number.isFinite(l.longitude)&&Math.abs(l.longitude)<=180);
 if(!locations.length)return '<section class="facility-map"><h2>Location map</h2><p>No verified map reference is available. Confirm the address with the facility.</p></section>';
 return '<section class="facility-map"><h2>Location map</h2><p class="small">Map references may show a city or ZIP area rather than the building. Confirm the facility address before travelling.</p><p class="small">Loading a map connects to OpenStreetMap.</p>'+locations.map((l,i)=>`<button type="button" data-map-index="${i}">Load map: ${esc(l.city)}, ${esc(l.state)} (${esc(l.precision)} reference)</button>`).join('')+'<div id="facilityMapCanvas" aria-live="polite"></div></section>';
}
function coverageSummary(showPublished=false){
  if(!catalogReady)return showPublished?'<section class="panel" id="publicCoverage" aria-live="polite"><p>Loading directory coverage…</p></section>':'';
  const validStates=new Set('AL AK AZ AR CA CO CT DE FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY'.split(' '));
  const states=new Set();
  for(const entry of DIRECTORY){
    for(const state of String(entry.states||'').toUpperCase().split(/[;,/|]+/)){if(validStates.has(state.trim()))states.add(state.trim())}
    for(const location of entry.locations||[]){const state=String(location.state||'').toUpperCase().trim();if(validStates.has(state))states.add(state)}
  }
  return `<section class="panel"><p><strong>${(catalogCounts?.entry_count??summary?.listing_count??DIRECTORY.length).toLocaleString()}</strong> imaging facilities listed. Prices show where a facility publishes them.</p></section>`;
}
function initialSearch(){const q=state.location.trim().toLowerCase();const leads=q&&!/^\d/.test(q)?DIRECTORY.filter(d=>d.area.toLowerCase().includes(q)||d.states.toLowerCase()===q):[];return `<div class="panel"><h2>${state.location?'Browse imaging centers in your state':'Where would you like to search?'}</h2><p>${state.mod&&state.body.trim()?'Your exam details are ready. Enter a city or state to find options.':'Select your state to browse imaging centers. All other filters are optional.'}</p><p class="small" id="catalogStatus" role="status">${esc(catalogStatus())}</p><div class="actions">${import.meta.env?.PROD?'':'<button id="sampleSearch">Try sample: knee MRI in Cincinnati</button>'}<button id="browseDirectory">Browse all facilities</button></div>${import.meta.env?.PROD?'':'<p class="small">The sample is a demonstration search, not a recommendation for a medical test.</p>'}<p class="small">Enter a city or ZIP to see how far each facility is.</p>${leads.length?'<h3>Directory locations in your search area</h3><p class="small">Entries may cover multiple locations. Service availability and exact addresses require confirmation.</p>'+leads.map(d=>`<div class="lead"><strong>${esc(d.name)}</strong><p>${esc(d.area)}</p><a href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">Check provider locations</a></div>`).join(''):''}</div>`}
function groupedCards(found){
 let listings=[...found,...(state.programs||[]),...(state.programEntries||[]).map(e=>directoryOffer(e,state)),...(state.nearbyUnpriced||[]).map(e=>directoryOffer(e,state))];
 const isPriced=o=>o.directory_only?!!o.published_prices?.some(p=>['MRI','CT'].includes(p.service)):Number.isFinite(o.amount)&&!['quote','conflict'].includes(o.type);
 const miles=o=>Number.isFinite(o.distance_miles)?o.distance_miles:Infinity;
 listings.sort((a,b)=>(isPriced(b)-isPriced(a))||((!state.sort||state.sort==='distance')?(miles(a)<miles(b)?-1:miles(a)>miles(b)?1:0):0));
 const zipResults=arrangeZipResults(listings,state.spatialActive ? "" : state.location);
 listings=(!state.nearToMe && (!state.sort || state.sort==='distance')) ? mostPricesFirst(zipResults.offers) : zipResults.offers;
 const page=paginateGroups([listings],state.resultsPage||0);
 if(!page.total)return '';
 const [cards]=page.items;
 const pagination=page.pages>1?`<nav class="row between" aria-label="Imaging center results pages"><span role="status">Showing ${page.start}–${page.end} of ${page.total} listings · Page ${page.current+1} of ${page.pages}</span><div class="row"><button type="button" data-results-page="${page.current-1}" ${page.current===0?'disabled':''}>Previous</button><button type="button" data-results-page="${page.current+1}" ${page.current===page.pages-1?'disabled':''}>Next</button></div></nav>`:'';
 const notice=zipResults.zip&&!zipResults.exact&&page.current===0?`<div class="notice zip-results-notice" role="status"><strong>No matching listings in ZIP ${esc(zipResults.zip)}</strong><p>We don’t have any fixed-price centers in our database for this ZIP code. Showing nearby centers and hospitals.</p></div>`:'';
 return notice+cards.map(card).join('')+pagination;
}
function catalogStatus(){if(!catalogReady&&!summary?.spatial_api_version&&summary?.listing_count)return `Directory available: ${summary.listing_count} researched entries. Browse the directory for full details.`;return catalogReady?`Directory loaded: ${catalogCounts?.entry_count??DIRECTORY.length} researched entries · ${catalogCounts?.offer_count??offers.filter(o=>!o.directory_only).length} mapped price offers. Entries can represent facilities, branches or programs; coverage is limited.`:catalogError?'The full directory is temporarily unavailable. You can still search; choose Browse all facilities to retry.':'The full directory is loading. You can search now using your city, state or ZIP.'}
function chatDisabled(){if(account?.tenant!=='guest')return false;return state.chatBlocked||(state.conversationId?(state.usage[state.conversationId]||0)>=5:Object.keys(state.usage).length>=3)}
function guestLimitExplanation(){
 if(state.chatLimitReason==='hourly')return 'Hourly guest chat limit reached. Try again after the next hour begins. Signing out does not reset this limit.';
 if(state.chatLimitReason==='daily')return 'Daily guest chat capacity reached. Please try again tomorrow (UTC).';
 if(state.conversationId&&(state.usage[state.conversationId]||0)>=5&&Object.keys(state.usage).length<3)return 'This conversation has used its 5 messages. You can start another conversation below.';
 return 'This guest session has used its chat allowance. Search and comparison remain available.';
}
function guestChatControls(){
 const limited=chatDisabled();
 const clear=state.messages.length?'<button id="newGuestChat" type="button" class="link-button">Clear</button>':'';
 return `<div class="actions">${CHAT_QUESTIONS.map(t=>`<button type="button" data-starter="${esc(t)}" ${limited?'disabled':''}>${esc(t)}</button>`).join('')}</div>${clear}${limited?'<p role="alert">'+esc(guestLimitExplanation())+'</p>':''}`;
}
function slotLabel(s){return new Date(s.date+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})+' · '+(s.period==='morning'?'Morning, 8 to noon':'Afternoon, noon to 5');}
function bookingSummary(b){return `<dl class="booking-summary"><dt>Facility</dt><dd>${esc(b.clinic_name)}</dd><dt>Location</dt><dd>${esc(b.location||'Confirm with the facility')}</dd><dt>Exam</dt><dd>${esc([b.service,b.exam].filter(Boolean).join(' · '))} · ${esc(contrastLabel(b.contrast))}</dd><dt>Preferred times</dt><dd>${b.slots.map(s=>esc(slotLabel(s))).join('<br>')}<br>${esc(BOOKING_ZONES[b.timezone])} time</dd><dt>Price</dt><dd>${esc(b.price_text||'Clinic will confirm the exact total.')}</dd></dl>`;}
const FAQ_GROUPS=[["Prices", [["What does “Quote required” mean?", "The facility doesn’t publish a price for this exam. Tap Request a time or call, and ask for the all-in self-pay price."], ["Is the listed price final?", "The facility confirms the exact exam and total when it calls you. Each listing shows where the price came from and the date we checked."], ["What’s included in the price?", "Each listing shows what it covers, such as the radiologist’s read and contrast. Where a listing doesn’t say, ask the facility."]]], ["Requesting a time", [["How does Request a time work?", "Pick up to 3 time windows. The facility calls you to confirm the exact time."], ["How soon will I hear back?", "Facilities get your request by secure email and are asked to respond within one business day. Your request page shows its status."], ["Can I ask more than one facility?", "Yes, up to 3 at a time. When one facility schedules you, we close your other requests for that exam."], ["Can I cancel?", "Yes. Tap Cancel request on your request page."]]], ["Imaging orders", [["Do I need an order?", "Most MRI and CT scans need one from a clinician. Ask the facility how it receives the order, and put your MySelfPay reference code on it."], ["Who can write the order?", "Physicians, nurse practitioners and physician assistants can, and in many states chiropractors and podiatrists too. Your own clinician is the place to start."]]], ["Your information", [["Why a phone number?", "We text you a code to confirm it’s you, and the facility uses the number to call you."], ["What do you keep about me?", "Your first name and phone number, until 30 days after your last request closes. Tap Forget me to remove them sooner."], ["Who runs MySelfPay?", "One Smarter, Inc., in Dayton, Ohio."]]]];
function faqHtml(){return `<section class="faq" id="faq" aria-label="Frequently asked questions"><h2>Frequently asked questions</h2>${FAQ_GROUPS.map(([g,items],i)=>`<details class="faq-group"${i===0?' open':''}><summary>${g}</summary>${items.map(([q,a])=>`<h3>${q}</h3><p>${a}</p>`).join('')}</details>`).join('')}</section>`}
function home(){return `<section class="welcome-intro"><div><div class="eyebrow">WELCOME TO MYSELFPAY</div><h1>Find self-pay MRI and CT near you.</h1><p class="welcome-lead">See published prices and what’s included, and call the facility in one tap.</p><p>You can explore self-pay options whether you have health coverage or are paying entirely yourself. Your facility confirms the exact service, eligibility and final price.</p><div class="actions"><button class="primary" id="welcomeBegin">${'Find imaging options'}</button></div></div><aside class="welcome-account"><h2>Search prices free.</h2><p>Use Quick searches anytime.</p><p class="small">Enter your exam and city to see prices near you.</p></aside></section>${faqHtml()}<section class="welcome-steps" aria-label="How MySelfPay works"><div><span class="step-number">1</span><h3>Tell us what you need</h3><p>Choose an imaging service and location, or describe your search.</p></div><div><span class="step-number">2</span><h3>See the details</h3><p>Review prices, included fees and restrictions for each facility.</p></div><div><span class="step-number">3</span><h3>Request a time</h3><p>Pick up to 3 windows and the facility calls to confirm.</p></div></section><section class="welcome-paths"><h2>How would you like to begin?</h2><div class="welcome-choices"><button class="journey-card" data-journey="search"><strong>Search for a service</strong><span>Choose your imaging exam and location.</span></button><button class="journey-card" data-journey="agent"><strong>Quick searches</strong><span>Pick a question and see matching facilities.</span></button></div></section>${coverageSummary(true)}`;}
function nearControl(){return `<div class="near-control"><button type="button" id="nearToMe" role="switch" aria-checked="${state.nearToMe?'true':'false'}" class="near-switch"><span class="near-switch-track" aria-hidden="true"><span class="near-switch-thumb"></span></span><span>Near me</span></button>${state.nearToMe?`<span class="near-info ${state.nearInfoOpen?'is-open':''}"><button type="button" class="near-info-icon" aria-label="About nearest results" aria-expanded="${state.nearInfoOpen?'true':'false'}" aria-describedby="near-info-tooltip">i</button><span id="near-info-tooltip" role="tooltip">Near me shows the nearest centers first. Complete details, such as prices, email or directions, may not be available for some centers.</span></span>`:''}</div>`;}
function nativeSearch(){const total=results.length+(state.programs||[]).length+(state.programEntries||[]).length+(state.nearbyUnpriced||[]).length;const filters=!state.searched||state.nativeFiltersOpen;if(state.mode==='agent')return null;return `<div class="native-search-view"><section class="native-filter-panel" ${filters?'':'hidden'}><div class="native-filter-heading"><h1>Search &amp; filters</h1>${state.searched?'<button type="button" data-native-action="close-filters" aria-label="Close search filters">×</button>':''}</div><form id="searchForm">${searchFields()}<button class="primary native-find-options" ${state.nativeBusy?'disabled':''}>${state.nativeBusy?'Finding options…':'Find options'}</button></form></section><section class="native-results-panel" ${filters?'hidden':''}>${locationPending()?locationPrompt():`<div class="native-results-heading"><h2>${total} offers</h2>${nearControl()}</div><button type="button" data-native-action="filters" class="native-edit-filters">Search &amp; filters</button>${groupedCards(results)||'<div class="panel"><h2>No matching centers</h2><p>Try another state or adjust your optional filters.</p><button type="button" data-native-action="filters">Edit search</button></div>'}`}</section>${state.selected.length?`<div class="native-compare-bar"><span>${state.selected.length} selected</span><div class="row"><button id="compare" type="button">Compare selected</button><button id="clearCompare" type="button" aria-label="Clear comparison selections">×</button></div></div>`:''}</div>`;}
function search(){if(state.nativeApp&&state.mode!=='agent')return nativeSearch();const found=results;const total=found.length+(state.programs||[]).length+(state.programEntries||[]).length+(state.nearbyUnpriced||[]).length;const searchControls=`<div class="tabs search-tabs"><button id="classic" class="${state.mode==='classic'?'active':''}">Search & filters</button><button id="agent" class="${state.mode==='agent'?'active':''}">Quick searches</button></div><div class="search-toolbar">${chips()}</div><div id="searchNotice" role="status"></div>${state.spatialActive&&!String(state.spatialStatus||'').startsWith('Showing centers across ')?`<p class="small" role="status">${esc(state.spatialStatus||'Location processing stays in this browser. Only an approximate area cell is sent to MySelfPay.')}</p>`:''}${state.saveStatus==='failed'?'<p class="notice" role="alert">This search was not saved. Results are still available; try searching again to retry saving.</p>':''}`;return `${!state.searched?`<div class="row between"><div><div class="eyebrow">SELF-PAY IMAGING</div><h1>Find and compare imaging options</h1><div class="muted">Compare published prices and know what to confirm.</div></div></div>${searchControls}`:''}<div class="grid ${state.searched?'search-results-grid':''} ${state.mode==='agent'?'agent-layout':''}"><div class="stack" style="align-self:start;min-width:0">${state.searched?searchControls:''}<aside class="panel"><details ${state.mode==='classic'||state.detailsOpen?'open':''}><summary>Search details</summary><form id="searchForm">${searchFields()}<button class="primary" style="width:100%">Find options</button></form></details></aside></div><section class="stack search-result-cards">${state.mode==='agent'?`<div class="panel"><h3>Quick searches</h3><div class="chat" id="chat">${state.messages.map(m=>`<div class="message ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')||'<div class="message">Pick a question and we show matching facilities.</div>'}</div>${guestChatControls()}</div>`:''}${!state.searched?initialSearch()+coverageSummary():locationPending()?locationPrompt():`<div class="row between"><h2>${total} facilit${total===1?'y':'ies'}</h2><div class="row">${nearControl()}</div></div><p class="small">Pick up to 3 to compare.</p>${groupedCards(found)||`<div class="panel"><h3>${state.noExamPrice?'No listed facility publishes a price for this exam':state.unlocatedOfferCount?'Distance results are incomplete':'No reviewed match for this search'}</h3>${state.unlocatedOfferCount?'<p>Some matching listings do not yet have verified facility coordinates. This does not mean no services are available. View the directory to review those listings while location data is being updated.</p>':''}<p>We have not changed your procedure. View the directory for additional listings. “With contrast” and “without and with contrast” remain separate.</p><button id="leads">View directory leads</button></div>`}`}${state.selected.length?`<div class="sticky row between"><span>${state.selected.length} option${state.selected.length===1?'':'s'} selected</span><div class="row"><button id="compare">Compare selected</button><button id="clearCompare" type="button" aria-label="Close comparison bar and clear all selections" title="Clear comparison selections">×</button></div></div>`:''}</section></div>`;}
function auth(){return '<section class="panel"><h1>MySelfPay account</h1></section>';}
function directoryPriceDetails(o){return `<h2>Service details and prices</h2>${o.entry.workbook_prices&&o.entry.zip_codes?`<p><strong>ZIP codes:</strong> ${esc(o.entry.zip_codes)}</p>`:''}<dl class="directory-service-details">${[['MRI','mri'],['CT','ct'],['Other imaging','other']].map(([label,key])=>`<dt>${label}</dt><dd>${esc(o.entry[key]||'Not provided in this listing')}</dd>`).join('')}</dl>`;}
function hospitalPrices(o){const m={};const add=(svc,val)=>{const k=/\bct\b/i.test(svc)&&!/mri/i.test(svc)?'CT':/mri/i.test(svc)?'MRI':'';const n=Number(String(val||'').replace(/[^0-9.]/g,''));if(k&&n>0&&!(k in m))m[k]=n};(o.published_prices||[]).forEach(p=>{if(!/screening/i.test(String(p.text)+String(p.service)))add(p.service,(String(p.text).match(/\$\s?([\d,]+(?:\.\d+)?)/)||[])[1])});if(o.type==='fixed'&&o.amount!=null)add(o.service||state.mod||'MRI',o.amount);return JSON.stringify(m)}
function detail(id){const o=offers.find(x=>x.id===id);if(!o)return '<p>Listing unavailable. Please search again.</p>';const more=String(o.entry.additional||'').split(/\s+/).filter(url=>url.startsWith('https://'));const e=o.entry,where=addressOf(e)||e.coverage,restrictions=restrictionsOf(o),web=websiteOf(e),phone=String(e.phone||''),dial=phone.replace(/[^+0-9]/g,''),address=addressOf(e);return `<section class="facility-reference"><button id="back" class="flow-copy-link page-back">← Back to results</button><div class="facility-overview-grid"><div class="facility-summary-column"><section class="flow-card facility-reference-hero"><span class="badge ${o.type==='fixed'?'':'warn'}">${typeLabel(o)}</span><h1>${esc(e.name)}</h1><p class="muted">${esc(address||e.area||where||'Location to be confirmed')}</p><div class="price ${/\$\s*\d/.test(String(cardPriceSummary(o)??price(o)))?'compact-service-prices ':''}${o.directory_only&&o.published_prices?.length?'published-prices':''}">${esc(cardPriceSummary(o)??price(o))}</div><p>${esc(scopeLine(o))}</p>${Number.isFinite(o.distance_miles)?`<p class="muted small">${esc(distanceLabel(o))}</p>`:''}<p><strong>Order:</strong> ${esc(orderText(o))}</p>${e.is_test_center?'<p class="flow-help">Fictional test center · no medical care is provided.</p>':''}</section><section class="flow-card facility-contact-card">${o.included&&!/^Confirm/i.test(o.included)?`<h2>What the price includes</h2><p>${esc(o.included)}</p>`:'<h2>Confirm with the facility</h2><p>Confirm the exact exam and the all-in self-pay price before you go.</p>'}<div class="facility-reference-links">${dial.length>=8?`<a class="flow-outline" href="tel:${esc(dial)}">Call ${esc(formatPhone(phone))}</a>`:''}${address?`<a class="flow-outline" href="https://www.google.com/maps/search/?api=1&amp;query=${esc(encodeURIComponent(String(e.name).split(' — ')[0]+', '+address))}" target="_blank" rel="noopener noreferrer">Directions</a>`:''}${web?`<a class="flow-outline" href="${esc(web)}" target="_blank" rel="noopener noreferrer">Website</a>`:''}</div></section></div><section class="flow-card facility-more-details"><h2>More facility and price details</h2>${o.directory_only?directoryPriceDetails(o):''}${address?'':`<p>${esc(where||'Confirm the location with the facility.')}</p>`}${restrictions.length?`<h2>Good to know</h2><ul>${restrictions.map(text=>`<li>${esc(text)}</li>`).join('')}</ul>`:''}${[...new Set(more)].map(url=>`<p><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">More from this facility</a></p>`).join('')}${facilityMap(e)}</section></div><section class="flow-card facility-questions-card"><h2>Questions to ask the facility</h2><ul class="checklist">${questions(o).map(q=>`<li>${esc(q)}</li>`).join('')}</ul></section><div data-hospital-rates data-zip="${esc((String(state.location||'').match(/\b\d{5}\b/)||[String(account?.zip_code||'').slice(0,5)])[0])}" data-modality="${esc([state.mod,o.service,o.entry?.service].filter(Boolean).join(' '))}" data-prices="${esc(hospitalPrices(o))}"></div>${e.booking_id?`<div class="facility-request-action"><button class="flow-primary" type="button" data-appointment="${esc(e.booking_id)}" data-booking-offer="${esc(o.directory_only?'':o.id||'')}">Request a Time</button><p class="flow-help">Use your verified mobile account to request a time. The center confirms your appointment.</p></div>`:''}</section>`;}

const ASK_FACILITY='Ask the facility';
function orderText(o){return o.order&&!/^(Review the facility restrictions|Not established in this directory|Confirm)/i.test(o.order)?o.order:'Order required. Ask how to send it, and use your reference code.'}
function comparePrice(o){const s=cardPriceSummary(o);if(s)return s.split('\n').join(' · ');const p=price(o);return p==='Ask for a price'||!o.mod?p:p+' · '+o.mod}
function compareExtras(o){return (o.published_prices||[]).filter(p=>['MRI','CT'].includes(p.service)).map(p=>p.text).join(' ')}
function compareExam(o){const known=o.contrast&&o.contrast!=='unknown'?contrastLabel(o.contrast):'';if(!o.mod||/^imaging services$/i.test(o.mod))return known||null;return known?o.mod+' · '+known:o.mod}
function compareActions(o){const e=o.entry,ph=phoneOf(e),addr=addressOf(e);const out=[e.booking_id?`<button type="button" data-appointment="${esc(e.booking_id)}" data-booking-offer="${esc(o.directory_only?'':o.id||'')}">Request a Time</button>`:'',ph?telLink(ph,'call','Call '+ph):'',addr?`<a href="https://www.google.com/maps/search/?api=1&amp;query=${esc(encodeURIComponent(String(e.name).split(' — ')[0]+', '+addr))}" target="_blank" rel="noopener noreferrer">Directions</a>`:''].join('');return out?`<div class="card-actions" aria-label="Contact ${esc(e.name)}">${out}</div>`:null}
function compare(){const chosen=state.selected.map(id=>offers.find(o=>o.id===id)).filter(Boolean);
const rows=[
['Price',o=>`<strong class="compare-price">${esc(comparePrice(o))}</strong><br><span class="small muted">${/\$/.test(cardPriceSummary(o)??price(o))?'Published':'Quote required'}</span>${compareExtras(o)?`<br><span class="small muted">${esc(compareExtras(o))}</span>`:''}`,true],
['Exam priced',o=>compareExam(o)&&esc(compareExam(o)),true],
['Included',o=>o.included&&!/^Confirm/i.test(o.included)?esc(o.included):null],
['Order',o=>esc(orderText(o)),true],
['Address',o=>addressOf(o.entry)?esc(addressOf(o.entry)):null],
['Phone',o=>phoneOf(o.entry)?telLink(phoneOf(o.entry),'',phoneOf(o.entry)):null],
['Next step',compareActions]];
const shown=rows.filter(([,value,always])=>always||chosen.some(o=>value(o)));
return `<h2>Compare facilities</h2><p class="notice">Compare the same exam. Each facility confirms the final price when it calls.</p><div class="comparison-scroll"><table class="comparison-table"><thead><tr><th scope="col"><span class="sr-only">Details</span></th>${chosen.map(o=>`<th scope="col">${esc(o.entry.name)}<span class="compare-sub">${esc([o.region,Number.isFinite(o.distance_miles)?distanceLabel(o):''].filter(Boolean).join(' · '))}</span></th>`).join('')}</tr></thead><tbody>${shown.map(([label,value])=>`<tr><th scope="row">${label}</th>${chosen.map(o=>{const v=value(o);return `<td>${v||`<span class="muted">${ASK_FACILITY}</span>`}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function request(o){const ph=phoneOf(o.entry),exam=[state.body,o.mod].filter(Boolean).join(' ')||o.mod;return `<h2>Ask for a self-pay price</h2><p>${esc(o.entry.name)}</p>${ph?`<p class="card-actions">${telLink(ph,'call','Call '+ph)}</p>`:'<p>Use the facility website to reach them.</p>'}<p>When you call, say you are paying yourself and ask for the all-in price for your ${esc(exam)}${state.contrast&&state.contrast!=='unknown'?` (${esc(contrastLabel(state.contrast).toLowerCase())})`:''}.</p><h3>Questions to ask</h3><ul class="checklist">${questions(o).map(q=>`<li>${esc(q)}</li>`).join('')}</ul><p class="small muted">Published reference: ${esc(price(o))} · ${typeLabel(o)}</p>`;}
function directory(){const priced=offers.filter(o=>!o.directory_only).length;return `<h2>All imaging facilities</h2><p>${formatCount(DIRECTORY.length)} imaging facilities listed. Prices show where a facility publishes them.</p>${control('dirSearch','Search by name, city, state or ZIP','<input id="dirSearch" placeholder="e.g. Dayton, OH">')}<div class="row dir-filters"><label class="dir-switch"><input type="checkbox" id="dirPriced"> Published prices only</label><div class="field"><label for="dirExam">Exam</label><select id="dirExam"><option value="">MRI or CT</option><option value="MRI">MRI</option><option value="CT">CT</option></select></div></div><p id="dirCount" role="status"></p><div id="dirRows"></div><div class="actions"><button id="dirPrev" type="button">Previous</button><button id="dirNext" type="button">Next</button></div>`;}
function directoryRows(entries){return visible(entries).map(d=>{const ph=phoneOf(d),addr=addressOf(d),id='directory-'+encodeURIComponent(d.booking_id||d.name),where=cityState(d),has=hasPublishedPrice(d);const acts=[ph?telLink(ph,'call','Call '+ph):'',`<a href="https://www.google.com/maps/search/?api=1&amp;query=${esc(encodeURIComponent([d.name,addr||where].filter(Boolean).join(' ')))}" target="_blank" rel="noopener noreferrer">Directions</a>`,d.booking_id?`<button type="button" data-appointment="${esc(d.booking_id)}" data-booking-offer="">Request a Time</button>`:'',`<button type="button" data-detail="${esc(id)}">See prices</button>`].join('');return `<details class="lead"><summary><strong>${esc(d.name)}</strong><span class="compare-sub">${esc(where)}</span></summary>${d.is_test_center?'<p class="notice">TEST CENTER — no medical care</p>':''}<div class="card-actions">${acts}</div>${has?`<p><strong>MRI:</strong> ${esc(d.mri)}<br><strong>CT:</strong> ${esc(d.ct)}</p>`:'<p class="muted">No published price. Call to ask.</p>'}${addr?`<p class="small muted">${esc(addr)}</p>`:''}${d.source?`<p class="small"><a href="${esc(d.source)}" target="_blank" rel="noopener noreferrer">Provider source</a></p>`:''}<span class="badge neutral">${esc(d.category)}</span></details>`}).join('');}
function voice(){return `<h2>Voice conversation preview</h2><p>No microphone or speech service is connected. Choose a predefined sample question to run the same guided search.</p><div class="field"><label for="transcript">Select sample question</label><select id="transcript">${CHAT_QUESTIONS.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><button id="useTranscript" class="primary">Use selected question</button>`;}

const BOOKING_STATUS={requested:'Request sent',voicemail:'The facility tried to reach you',scheduled:'Time confirmed',unable:'This facility couldn’t schedule',expired:'Request expired',cancelled:'Request closed'};
function bookingSlots(draft,options){return `<button type="button" id="bookingTimeBack" class="booking-back">← Back to results</button><h2>Request a Time</h2><p class="eyebrow">STEP 1 OF 2</p><div class="booking-clinic-card"><h3>${esc(draft.clinic_name)}</h3><p>${esc(draft.price_text)}</p></div><p>Pick up to 3 windows. These are your preferred windows; the facility calls to confirm the exact time.</p><form id="bookingSlots"><p class="small muted">Times shown in ${esc(BOOKING_ZONES[draft.timezone]||'Eastern')} time.</p><div id="bookingTimePicker"></div><p id="bookingError" role="alert"></p><button type="submit" class="primary">Continue</button></form>`;}
function bookingContact(draft){return `<h2>Confirm your request</h2>${bookingSummary(draft)}<p>Verified mobile: ${esc(draft.phone)}</p>`;}
function examText(b){const service=b.service&&!/^please contact me$/i.test(b.service)?b.service:'';const c={without:'without contrast',with:'with contrast',both:'without and with contrast'}[b.contrast]||'';return [[service,b.exam].filter(Boolean).join(' '),c].filter(Boolean).join(' ')}
function receiptTime(t){return Number.isFinite(Number(t))?new Date(Number(t)*1000).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}):''}
function requestBack(){let from='';try{from=sessionStorage.getItem('msp-back')||''}catch(e){}return from==='requests'?'<a class="flow-back-top page-back" href="#dashboard">← My requests</a>':'<a class="flow-back-top page-back" href="#search">← Back to results</a>'}
function receipt(b,token){const done=b.status==='scheduled',closed=['unable','expired','cancelled'].includes(b.status),exam=examText(b),facilityLine=[b.clinic_name,exam,b.clinic_phone?formatPhone(b.clinic_phone):''].filter(Boolean).map(esc).join(' · '),cal=done?calendarFile(b):null,tel=b.clinic_phone?esc(String(b.clinic_phone).replace(/[^+0-9]/g,'')):'',maps='https://www.google.com/maps/search/?api=1&amp;query='+esc(encodeURIComponent([b.clinic_name,b.location].filter(Boolean).join(' '))),sent=b.delivery==='sent'?'Request sent':'Request saved',stamp=receiptTime(b.created),current=b.status==='voicemail'?3:2;return `<section class="reference-request-page">${requestBack()}<div class="flow-status-hero"><span class="flow-success-icon ${closed?'flow-status-muted':''}" aria-hidden="true">${closed?'–':'✓'}</span><h1>${esc(b.status==='requested'?sent:BOOKING_STATUS[b.status])}</h1><p class="booking-follow-up">${done?(b.approved_slot?`${esc(b.clinic_name)} set your ${esc(exam)} for ${esc(approvedSlotLabel(b.approved_slot))}.`:'Your request is confirmed. Call the facility to confirm the exact time.'):closed?'This request is closed. You can try another facility when you are ready.':`${esc(b.clinic_name)} has your request. They’ll call ${esc(b.contact_phone?formatPhone(b.contact_phone):'you')} to confirm a time.`}</p><div class="flow-reference"><span class="flow-reference-id" id="bookingCode">${esc(groupCode(b.id))}</span><button type="button" class="flow-copy-code" id="copyBookingCode" data-code="${esc(b.id)}">Copy</button></div><p class="flow-reference-note">Give this code to the facility with your order.</p><p class="flow-facility-line">${facilityLine}</p></div>${done?`<section class="flow-card"><h2>Your appointment</h2><h3>${esc(b.clinic_name)}</h3><div class="approved-appointment"><strong>Your time</strong><p>${esc(approvedSlotLabel(b.approved_slot))}</p></div><p>${b.approved_slot?.source==='custom'?'The facility chose a different time than your preferred windows. ':''}To change the time, call ${esc(b.clinic_name)}.</p><p>Bring your imaging order and your reference code. The facility tells you anything else when it calls.</p><p>${esc(b.location||'Confirm the location with the facility.')}</p><div class="flow-card-actions"><a class="flow-outline" href="${maps}" target="_blank" rel="noopener noreferrer">Directions</a>${tel?`<a class="flow-outline" href="tel:${tel}">Call ${esc(b.clinic_phone)}</a>`:''}${cal?`<a class="flow-outline" href="${cal.href}" download="${esc(cal.filename)}">Add to calendar</a>`:''}</div></section>`:closed?'':`<section class="flow-card"><ol class="flow-progress"><li class="complete"><span aria-hidden="true">✓</span><strong>${sent}${stamp?` ${esc(stamp)}`:''}</strong></li><li class="${b.status==='voicemail'?'complete':''}"${current===2?' aria-current="step"':''}><span>2</span><strong>Facility calls you</strong></li><li${current===3?' aria-current="step"':''}><span>3</span><strong>Time confirmed</strong></li></ol></section><section class="flow-card"><h2>While you wait</h2><p>Ask the facility how to send your imaging order, and give them your reference code. The facility confirms the time and the final price when it calls.</p></section>`}<details class="flow-card flow-receipt-details" open><summary>View request details</summary>${bookingSummary(b)}</details>${closed?'':`<div id="receiptCancel" data-facility="${esc(b.clinic_name)}" data-confirmed="${done?'1':''}"></div>`}<div class="flow-page-actions">${!done&&tel?`<a class="flow-primary" href="tel:${tel}">Call the facility</a>`:''}<a class="flow-outline" href="#dashboard">My requests</a></div><button type="button" class="flow-copy-link" id="copyBookingLink">Copy request link</button><p id="bookingActionStatus" role="status"></p></section>`;}
function clinicGate(id,token){return `<section class="reference-request-page"><section class="flow-card flow-center-gate"><p class="eyebrow">REQUEST ${esc(id)}</p><h1>Enter your code</h1><p>A 6-digit code is sent automatically to your center’s booking email. It works once, for 10 minutes.</p><p id="clinicCodeStatus" role="status" class="flow-help"></p><form id="clinicVerify"><label class="flow-label">Six-digit email code<input id="clinicCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></label><button class="flow-dark" id="clinicVerifyButton">Open request</button></form><button type="button" id="clinicCodeSend" class="flow-text-button">Send verification code</button><p id="clinicError" class="flow-error" role="alert"></p></section></section>`;}
function clinicPage(b,id){if(['scheduled','unable','expired','cancelled'].includes(b.status))return `<section class="reference-request-page"><div class="flow-status-hero"><span class="flow-success-icon" aria-hidden="true">✓</span><h1>${b.status==='scheduled'?'Request approved':'Request closed'}</h1><span class="flow-reference-id">${esc(id)}</span>${b.status==='scheduled'?`<div class="approved-appointment"><strong>Approved appointment</strong><p>${esc(approvedSlotLabel(b.approved_slot))}</p></div>`:''}<p id="clinicOutcome" role="status">${esc(BOOKING_STATUS[b.status])}</p><p>The patient sees this update in their dashboard. Their name and contact details are hidden on this page.</p></div><a class="flow-outline" href="/for-imaging-centers">For imaging centers</a></section>`;return `<section class="reference-request-page"><div class="flow-center-heading"><p class="eyebrow">REQUEST ${esc(id)}</p><p id="clinicCountdown" class="flow-help" role="timer"></p><h1>${esc(b.first_name||"Appointment request")}</h1></div><section class="flow-card">${b.phone?`<a class="flow-primary" href="tel:${esc(b.phone.replace(/[^+0-9]/g,''))}">Call ${esc(b.phone)}</a>`:''}<dl class="flow-center-summary"><dt>Exam</dt><dd>${esc([b.service,b.exam].filter(Boolean).join(' · '))}</dd><dt>Price shown</dt><dd>${esc(b.price_text)}</dd></dl></section><section class="flow-card"><h2>Preferred times</h2><div id="clinicAppointment"></div></section><section class="flow-card"><h2>Review and approve request</h2><p id="clinicOutcome" role="status" class="flow-help">${esc(BOOKING_STATUS[b.status])}</p><div class="booking-outcomes">${[['scheduled','Approve request'],['voicemail','Follow up with patient'],['unable','Decline request']].map(([value,label])=>`<button class="${value==='scheduled'?'flow-dark':'flow-outline'}" data-booking-status="${value}">${label}</button>`).join('')}</div><p id="clinicError" class="flow-error" role="alert"></p></section><p class="flow-help">Approval and status updates appear in the user and admin dashboards.</p><button class="flow-copy-link" id="clinicLock">Lock request</button></section>`;}

return {home,search,auth,detail,compare,request,directory,directoryRows,voice,esc,price,contrastLabel,bookingSummary,bookingSlots,bookingContact,receipt,clinicGate,clinicPage};
}
